\begin{proof}
The only nontrivial constraint is~\eqref{eq:sa_csp_two}. Fix $T \subseteq S \subseteq W$ with $|S| \leq r - 1$ and $\beta \in \{ 0, 1 \}^T$. Let $T_1 = \beta^{-1}(1)$ and $T_0 = \beta^{-1}(0)$. 
\begin{align*}
x_{T, \beta} &= \sum_{\substack{T_2,\ldots, T_{\ell}: \\ T_0 = T_2 \cupdot \ldots \cupdot T_{\ell}}} y_{T_1 \cup \{ p \}|T_2|\dots|T_{\ell}} \\
&= \sum_{\substack{T_2,\ldots, T_{\ell}: \\ T_0 = T_2 \cupdot \ldots \cupdot T_{\ell}}}
\sum_{\substack{S_1, \dots, S_{q} : \\ S = S_1 \cupdot  \ldots \cupdot S_{q} \mbox{ and} \\ T_i = S_i \cap T~ \forall i \in [\ell]}}
 y_{S_1 \cup \{ p \}|S_2|\dots|S_{q}} \\
 & = \sum_{S_1 : T_1 = S_1 \cap T}
  \bigg(
 \sum_{\substack{T_2,\ldots, T_{\ell}: \\ T_0 = T_2 \cupdot \ldots \cupdot T_{\ell}}}
\sum_{\substack{S_2, \dots, S_{q} : \\ S = S_1 \cupdot  \ldots \cupdot S_{q} \mbox{ and} \\ T_i = S_i \cap T~ \forall i \in \{ 2, \dots, \ell \} }}
 y_{S_1 \cup \{ p \}|S_2|\dots|S_{q}} \bigg) \\
  & = \sum_{S_1 : T_1 = S_1 \cap T}
  \bigg(
\sum_{\substack{S_2, \dots, S_{q} : \\ S = S_1 \cupdot  \ldots \cupdot S_{q}}}
 y_{S_1 \cup \{ p \}|S_2|\dots|S_{q}} \bigg) \\
      & = \sum_{S_1 : T_1 = S_1 \cap T}
   \sum_{\alpha \in \{ 0 , 1\}^S : \alpha^{-1}(1) = S_1} x_{S, \alpha} 
   = \sum_{\alpha \in \{ 0 , 1\}^S : \alpha|_T = \beta} x_{S, \alpha}.
 \end{align*}
\end{proof}
